User: In the diagram, $R$ is on $QS$ and $QR=8$. Also, $PR=12$, $\angle PRQ=120^\circ$, and $\angle RPS = 90^\circ$. What is the area of $\triangle QPS$? [asy]
//C19
size(10cm); // ADJUST
import olympiad;

// Point coordinates
pair r = (0, 0);
pair q = (-8, 0);
pair p = 12 * dir(60);
pair s = (24, 0);

// draw lines
draw(p--s--r--p--q--r);

// labels
label("$R$", r, S);
label("$Q$", q, SW);
label("$S$", s, SE);
label("$P$", p, N);
label("$12$", r + (p - r) / 2, SE);
label("$8$", r + (q - r) / 2, S);
label("$120^\circ$", r, NW + 0.2 * E);

markscalefactor = 0.08;
draw(rightanglemark(r, p, s));
[/asy]
